// === Tab: mySketch ===
let wdrops = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
	frameRate(30);
	wdrops.push(new WDrop(100, 100));
}

function draw() {
	background("lightblue");
	for (let i = wdrops.length - 1; i >= 0; i--) {
		const d = wdrops[i];
		d.update();
		d.show();
		if (!d.isAlive) {
			wdrops.splice(i, 1);
		}
	}
	if (frameCount % 15) wdrops.push(new WDrop(random(width), random(height)));
}

function mouseDragged() {
	wdrops.push(new WDrop((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
}
function windowResized() {
	setup();
}

class WDrop {
	constructor(x, y) {
		this.x = x;
		this.y = y;
		this.r = 1;
		this.a = 255;
		this.isAlive = true
	}
	update() {
		this.r++;
		this.a-=4;
		if (this.a < 0) {
			this.a = 0;
			this.isAlive = false;
		}
	}
	show() {
		push();
		stroke(255, this.a*2);
		strokeWeight(map(this.a, 255, 0, 0.25, 5));
		noFill();
		ellipse(this.x, this.y, this.r+this.r, this.r+this.r)
		pop();
	}
}
